<?php
declare(strict_types=1);
/* Exports de lecture, sans génération IA ni mutation du registre. */
function emDate(string $date):string {return preg_match('/^(\d{4})-(\d{2})-(\d{2})$/D',$date,$m)?$m[3].'.'.$m[2].'.'.$m[1]:$date;}
function emLevel(int $score):string {return $score>=9?'Élevé':($score>=6?'Modéré':'Faible');}
function emColor(int $score):string {return $score>=9?'F6CECB':($score>=6?'F8E8AD':'DCEBDD');}
function emLabel(string $text,int $words=18):string {
    $text=trim(preg_replace('/^À VALIDER\s*[—:–-]\s*/u','',$text)??$text);
    $parts=preg_split('/\s+/u',$text)?:[];return count($parts)<=$words?$text:implode(' ',array_slice($parts,0,$words)).'…';
}
function emActionLabel(string $title):string {
    $t=trim(preg_replace('/^À VALIDER\s*[—:–-]\s*/u','',$title)??$title);
    if(str_starts_with($t,'Évaluer les réponses documentaires'))return 'Vérifier la fidélité et l’actualité des réponses documentaires';
    if(str_starts_with($t,'Décrire pour chaque usage ce que'))return 'Définir les actions permises et les validations humaines';
    $parts=preg_split('/[:;.,]/u',$t);$label=trim($parts[0]??$t);$label=preg_replace('/^Préparer puis conduire /u','Conduire ',$label)??$label;
    return mb_strlen($label)<=110?$label:'Mesure à examiner · texte complet dans les notes';
}
function emOwnerLabel(string $owner):string {
    $parts=preg_split('/[;,]/u',$owner);$first=trim($parts[0]??$owner);if(mb_strlen($first)<=75)return $first;
    foreach(['Pilotage IA'=>'Pilotage IA','Responsable formation'=>'Formation et référents métiers','Secteur IT'=>'Secteur IT','IT'=>'IT','Juridique'=>'Juridique','Responsable métier'=>'Responsable métier','Responsable du traitement'=>'Responsable du traitement','Responsables métiers'=>'Responsables métiers','Autorité compétente'=>'Autorité compétente'] as $prefix=>$label)if(str_starts_with($owner,$prefix))return $label.' · appuis dans les notes';
    return 'Responsable proposé dans les notes';
}
function emRiskNotes(array $r):string {
    $d=$r['data'];$lines=[$r['code'].' — '.$d['title'],'Version '.$r['version'].' ; statut '.exportStatus($d['status']),'PROPRIÉTAIRE DU RISQUE : '.$d['owner'],'PÉRIMÈTRE : '.$d['perimeter']."\n".$d['scope'],'SCÉNARIO : '.$d['scenario'],'CONSÉQUENCES : '.$d['impact'],'FONDEMENT ET LIMITES : '.$d['basis'],'CONTRÔLES CONNUS : '.$d['controls'],'COTATIONS : initiale '.$d['score'].' = P'.$d['p'].' × G'.$d['g'].' ; personnes '.$d['gp'].' ; mission '.$d['go'].' ; cible conditionnelle '.$d['target_score'].' ; actuelle '.($d['current']['score']??'Non évalué'),'SYNTHÈSE DES MESURES : '.$d['measures'],'PREUVES ATTENDUES : '.$d['proof'],'ÉCHÉANCES PROPOSÉES : '.$d['when'],'REVUE : '.emDate($d['next_review']),'SOURCES ET LIENS : '.$d['mapping']];
    foreach($r['actions'] as $a){$m=$a['data'];$lines[]='MESURE '.$a['id'].' — '.$m['title']."\nResponsable proposé : ".$m['owner']."\nÉchéance proposée : ".emDate($m['due'])."\nÉtat : ".exportStatus($m['status']).' ; vérification : '.($m['verification']??'Non vérifiée')."\nPreuves / références : ".$m['proof'];}
    foreach($r['assessments'] as $a)$lines[]='RÉÉVALUATION CONSIGNÉE : '.json_encode($a['data'],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);
    foreach($r['decisions'] as $a)$lines[]='DÉCISION CONSIGNÉE : '.json_encode($a['data'],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);
    $lines[]='Les notes reprennent les informations enregistrées sans en certifier l’exactitude. Les libellés abrégés à l’écran sont développés ici. Une mesure planifiée ou une cible ne prouve pas une réduction du risque. Un rôle applicatif ne constitue pas une délégation institutionnelle.';
    return implode("\n\n",$lines);
}
function emGroups(array $risks):array {
 $groups=[];foreach($risks as $r){$key=$r['data']['perimeter'];$groups[$key][]=$r;}$out=[];foreach($groups as $name=>$items)$out[]=['name'=>$name,'risks'=>$items];return $out;
}
function emPlan(array $risks,bool $annexes=true,bool $focus=false):array {
    if(!$risks||count($risks)>40)throw new InputError('Sélectionnez de 1 à 40 risques.');$n=count($risks);$actions=[];$high=0;$unknown=0;$decisionCount=0;
    foreach($risks as $r){$high+=(int)($r['data']['score']>=9);$unknown+=(int)($r['data']['current']===null);$decisionCount+=count($r['decisions']);foreach($r['actions'] as $a)$actions[]=['code'=>$r['code']]+$a['data'];}
    usort($actions,fn($a,$b)=>[$a['due'],$a['code'],$a['title']]<=>[$b['due'],$b['code'],$b['title']]);
    $slides=[['kind'=>'cover','title'=>$focus?$risks[0]['code'].' · Analyse du risque':'Maîtriser les risques liés à l’IA','subtitle'=>$focus?$risks[0]['data']['title']:'État-major · Synthèse pour préparer les arbitrages','notes'=>'Périmètre exporté : '.implode(', ',array_column($risks,'code')).'. Photographie du registre au '.(new DateTimeImmutable('now',new DateTimeZone('Europe/Zurich')))->format('d.m.Y H:i').' (Europe/Zurich). Aucun appel à un service IA lors de cet export. Les propositions restent à examiner.']];
    $slides[]=['kind'=>'overview','title'=>$focus?'La situation de ce risque':'La situation du registre','metrics'=>[[$n,'risque'.($n>1?'s':'').' sélectionné'.($n>1?'s':'')],[$high,'cotation'.($high>1?'s':'').' initiale'.($high>1?'s':'').' élevée'.($high>1?'s':'')],[$unknown,'sans réévaluation actuelle']],'lines'=>['Les cotations initiales sont des propositions de travail.','Les cibles supposent des mesures efficaces, à démontrer.','La situation actuelle exige un examen fondé sur des preuves.'],'notes'=>implode("\n",array_map(fn($r)=>$r['code'].' : initiale '.$r['data']['score'].' ; cible '.$r['data']['target_score'].' ; actuelle '.($r['data']['current']['score']??'Non évalué'),$risks))."\nUn score n’est pas une probabilité statistique. Les scores ne s’additionnent pas. Les seuils sont une convention du registre : faible 1–4, modéré 6–8, élevé 9–16."];
    if($focus){$r=$risks[0];$slides[]=['kind'=>'story','title'=>'Le scénario et ses conséquences','scenario'=>$r['data']['scenario'],'impact'=>$r['data']['impact'],'notes'=>emRiskNotes($r)];}
    else foreach(array_chunk(emGroups($risks),6) as $batch)$slides[]=['kind'=>'families','title'=>'Les domaines à protéger','rows'=>array_map(fn($g)=>[$g['name'],implode(', ',array_column($g['risks'],'code'))],$batch),'notes'=>'Regroupement de lecture pour la présentation, sans nouvelle classification ou cotation. '.implode("\n",array_map(fn($r)=>$r['code'].' — '.$r['data']['title']."\nConséquences : ".$r['data']['impact'],$risks))];
    if(!$focus){$rows=[];foreach(array_slice($risks,0,6) as $r)$rows[]=[$r['code'].' · '.$r['data']['title'],$r['data']['impact']];$slides[]=['kind'=>'impacts','title'=>'Les conséquences possibles pour votre organisation','rows'=>$rows,'notes'=>'Conséquences déclarées dans les fiches sélectionnées. Les six premières sont visibles ; toutes sont conservées dans les notes. Aucun incident réel établi par cet export. '.implode("\n",array_map(fn($r)=>$r['code'].' — '.$r['data']['impact'],$risks))];}
    $slides[]=['kind'=>'matrix','title'=>'La cartographie initiale proposée','risks'=>$risks,'notes'=>'Position initiale : gravité = maximum des conséquences pour les personnes et la mission ; vraisemblance de 1 à 4. La couleur n’établit pas l’acceptabilité et ne vaut pas autorisation. Une gravité 4 exige un examen renforcé. '.implode("\n",array_map(fn($r)=>$r['code'].' : P'.$r['data']['p'].' / G'.$r['data']['g'].' / score '.$r['data']['score'],$risks))];
    if($focus){$r=$risks[0];$slides[]=['kind'=>'comparison','title'=>'Proposition, cible et situation actuelle','values'=>[(string)$r['data']['score'],(string)$r['data']['target_score'],(string)($r['data']['current']['score']??'Non évalué')],'notes'=>'La cible est conditionnelle à l’efficacité des mesures. La cotation actuelle ne découle pas de l’écart entre initiale et cible. '.emRiskNotes($r)];}
    $counts=array_fill_keys(['planifiee','en_cours','preuve_soumise','verifiee'],0);foreach($actions as $a){if(array_key_exists($a['status'],$counts))$counts[$a['status']]++;}
    $slides[]=['kind'=>'actions','title'=>'Les mesures et leur niveau de preuve','counts'=>$counts,'total'=>count($actions),'notes'=>"Statuts exclusifs des mesures, sans déduire leur efficacité de leur seule existence. Les mesures vérifiées sont comptées à part ; une preuve soumise n’est pas encore vérifiée. Une même mesure n’est comptée qu’une fois.\n".implode("\n\n",array_map(fn($a)=>$a['code'].' : '.$a['title']."\nResponsable proposé : ".$a['owner'].' ; date proposée : '.$a['due']."\n".$a['proof'],$actions))];
    if($focus){foreach(array_chunk($actions,3) as $batch)$slides[]=['kind'=>'measuretable','title'=>'Mesures proposées · qui et quand','rows'=>array_map(fn($a)=>[emActionLabel($a['title']),emOwnerLabel($a['owner']),emDate($a['due'])],$batch),'notes'=>emRiskNotes($risks[0])];}
    $dates=[];foreach($actions as $a)$dates[$a['due']][]=$a;$dateRows=[];foreach($dates as $date=>$items)$dateRows[]=[emDate($date),count($items).' mesure'.(count($items)>1?'s':''),count(array_unique(array_column($items,'code'))).' risque'.(count(array_unique(array_column($items,'code')))>1?'s':'')];
    foreach(array_chunk($dateRows,6)?:[[]] as $i=>$rows)$slides[]=['kind'=>'calendar','title'=>'Le calendrier proposé'.($i?' · suite':''),'rows'=>$rows,'notes'=>"Les échéances proviennent des mesures enregistrées ; elles restent à valider avec responsables, moyens et disponibilités. La date ne constitue pas une autorisation de mise en œuvre.\n".implode("\n",array_map(fn($a)=>emDate($a['due']).' — '.$a['code'].' — '.$a['title'].' — '.$a['owner'],$actions))];
    $slides[]=['kind'=>'decisions','title'=>'Les arbitrages à préparer','decision_count'=>$decisionCount,'rows'=>[['Priorités et périmètre','Quels besoins et quels risques traiter en premier ?'],['Responsables et moyens','Qui instruit, qui décide, et avec quel temps disponible ?'],['Conditions et prochaine revue','Quelles preuves demander avant d’étendre un usage ?']],'notes'=>'Questions proposées pour la séance, pas des décisions déjà prises. Nombre de décisions présentes dans les fiches sélectionnées : '.$decisionCount.'. '.implode("\n",array_map(fn($r)=>$r['code'].' — propriétaire : '.$r['data']['owner'].' — revue : '.$r['data']['next_review'],$risks))."\n".implode("\n\n",array_map(fn($r)=>implode("\n",array_map(fn($d)=>json_encode($d['data'],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES),$r['decisions'])),$risks))];
    if($annexes)foreach($risks as $r){$rows=[];foreach($r['actions'] as $a){$m=$a['data'];$rows[]=[emActionLabel($m['title']),emDate($m['due']),exportStatus($m['status'])];}foreach(array_chunk($rows,3)?:[[]] as $i=>$part)$slides[]=['kind'=>'annex','title'=>$r['code'].' · '.emLabel($r['data']['title'],9).($i?' · suite':''),'risk'=>$r,'rows'=>$part,'notes'=>emRiskNotes($r)];}
    return $slides;
}
const EM_A='http://schemas.openxmlformats.org/drawingml/2006/main';
const EM_P='http://schemas.openxmlformats.org/presentationml/2006/main';
function emNode(DOMDocument $d,string $ns,string $name,array $attributes=[]):DOMElement {$e=$d->createElementNS($ns,$name);foreach($attributes as $k=>$v)$e->setAttribute($k,(string)$v);return $e;}
function emText(DOMDocument $d,string $name,float $x,float $y,float $w,float $h,string $text,int $size=20,string $color='202A25',bool $bold=false,?string $fill=null,string $align='l'):void {
    $xp=new DOMXPath($d);$xp->registerNamespace('p',EM_P);$tree=$xp->query('//p:spTree')->item(0);$id=200+$xp->query('//p:cNvPr')->length;
    $sp=emNode($d,EM_P,'p:sp');$nv=emNode($d,EM_P,'p:nvSpPr');$nv->appendChild(emNode($d,EM_P,'p:cNvPr',['id'=>$id,'name'=>$name]));$nv->appendChild(emNode($d,EM_P,'p:cNvSpPr'));$nv->appendChild(emNode($d,EM_P,'p:nvPr'));$sp->appendChild($nv);
    $pr=emNode($d,EM_P,'p:spPr');$xf=emNode($d,EM_A,'a:xfrm');$xf->appendChild(emNode($d,EM_A,'a:off',['x'=>(int)round($x*914400),'y'=>(int)round($y*914400)]));$xf->appendChild(emNode($d,EM_A,'a:ext',['cx'=>(int)round($w*914400),'cy'=>(int)round($h*914400)]));$pr->appendChild($xf);$geo=emNode($d,EM_A,'a:prstGeom',['prst'=>'rect']);$geo->appendChild(emNode($d,EM_A,'a:avLst'));$pr->appendChild($geo);if($fill){$f=emNode($d,EM_A,'a:solidFill');$f->appendChild(emNode($d,EM_A,'a:srgbClr',['val'=>$fill]));$pr->appendChild($f);}else $pr->appendChild(emNode($d,EM_A,'a:noFill'));$ln=emNode($d,EM_A,'a:ln');$ln->appendChild(emNode($d,EM_A,'a:noFill'));$pr->appendChild($ln);$sp->appendChild($pr);
    $body=emNode($d,EM_P,'p:txBody');$body->appendChild(emNode($d,EM_A,'a:bodyPr',['wrap'=>'square','lIns'=>'60000','rIns'=>'60000','tIns'=>'30000','bIns'=>'30000','anchor'=>'ctr']));$body->appendChild(emNode($d,EM_A,'a:lstStyle'));
    foreach(explode("\n",$text) as $line){$p=emNode($d,EM_A,'a:p');$ppr=emNode($d,EM_A,'a:pPr',['algn'=>$align]);$ppr->appendChild(emNode($d,EM_A,'a:buNone'));$p->appendChild($ppr);$r=emNode($d,EM_A,'a:r');$rp=emNode($d,EM_A,'a:rPr',['lang'=>'fr-CH','sz'=>$size*100,'b'=>$bold?'1':'0']);$f=emNode($d,EM_A,'a:solidFill');$f->appendChild(emNode($d,EM_A,'a:srgbClr',['val'=>$color]));$rp->appendChild($f);$rp->appendChild(emNode($d,EM_A,'a:latin',['typeface'=>'Arial']));$r->appendChild($rp);$t=emNode($d,EM_A,'a:t');$t->appendChild($d->createTextNode($line));$r->appendChild($t);$p->appendChild($r);$body->appendChild($p);}$sp->appendChild($body);$tree->appendChild($sp);
}
function emRemove(DOMDocument $d,array $names):void {$xp=new DOMXPath($d);$xp->registerNamespace('p',EM_P);foreach(iterator_to_array($xp->query('//p:sp')) as $sp){$n=$xp->query('p:nvSpPr/p:cNvPr',$sp)->item(0);if($n&&in_array($n->getAttribute('name'),$names,true))$sp->parentNode->removeChild($sp);}}
function emTable(DOMDocument $d,array $headers,array $rows,array $widths,float $y=1.42,float $rowH=.43,int $font=18):void {
    $xp=new DOMXPath($d);$xp->registerNamespace('p',EM_P);$xp->registerNamespace('a',EM_A);$tree=$xp->query('//p:spTree')->item(0);
    $frame=emNode($d,EM_P,'p:graphicFrame');$nv=emNode($d,EM_P,'p:nvGraphicFramePr');$nv->appendChild(emNode($d,EM_P,'p:cNvPr',['id'=>400+$xp->query('//p:cNvPr')->length,'name'=>'Tableau éditable']));$nv->appendChild(emNode($d,EM_P,'p:cNvGraphicFramePr'));$nv->appendChild(emNode($d,EM_P,'p:nvPr'));$frame->appendChild($nv);
    $xf=emNode($d,EM_P,'p:xfrm');$xf->appendChild(emNode($d,EM_A,'a:off',['x'=>(int)(.57*914400),'y'=>(int)($y*914400)]));$xf->appendChild(emNode($d,EM_A,'a:ext',['cx'=>(int)(array_sum($widths)*914400),'cy'=>(int)((.4+count($rows)*$rowH)*914400)]));$frame->appendChild($xf);
    $graphic=emNode($d,EM_A,'a:graphic');$gd=emNode($d,EM_A,'a:graphicData',['uri'=>EM_A.'/table']);$table=emNode($d,EM_A,'a:tbl');$table->appendChild(emNode($d,EM_A,'a:tblPr',['firstRow'=>'1','bandRow'=>'0']));$grid=emNode($d,EM_A,'a:tblGrid');foreach($widths as $w)$grid->appendChild(emNode($d,EM_A,'a:gridCol',['w'=>(int)($w*914400)]));$table->appendChild($grid);
    foreach([$headers,...$rows] as $ri=>$row){$tr=emNode($d,EM_A,'a:tr',['h'=>(int)(($ri===0?.4:$rowH)*914400)]);foreach($row as $ci=>$text){
        emText($d,'temp-cell',0,0,1,1,(string)$text,$ri===0?15:$font,$ri===0?'087A2A':'202A25',$ri===0||$ci===0);$temp=$tree->lastChild;$pbody=$xp->query('p:txBody',$temp)->item(0);$body=emNode($d,EM_A,'a:txBody');while($pbody->firstChild)$body->appendChild($pbody->firstChild);$tree->removeChild($temp);$bp=$body->firstChild;foreach(['lIns','rIns','tIns','bIns'] as $attr)$bp->setAttribute($attr,'0');$tc=emNode($d,EM_A,'a:tc');$tc->appendChild($body);$pr=emNode($d,EM_A,'a:tcPr',['marL'=>'60000','marR'=>'60000','marT'=>'30000','marB'=>'30000','anchor'=>'ctr']);foreach(['L','R','T','B'] as $edge){$line=emNode($d,EM_A,'a:ln'.$edge);$line->appendChild(emNode($d,EM_A,'a:noFill'));$pr->appendChild($line);}$fill=emNode($d,EM_A,'a:solidFill');$fill->appendChild(emNode($d,EM_A,'a:srgbClr',['val'=>$ri>0&&$ri%2===1?'F0F5F1':'FFFFFF']));$pr->appendChild($fill);$tc->appendChild($pr);$tr->appendChild($tc);
    }$table->appendChild($tr);}$gd->appendChild($table);$graphic->appendChild($gd);$frame->appendChild($graphic);$tree->appendChild($frame);
}

function emPaint(DOMDocument $d,array $s,int $number):void {
    if($s['kind']==='cover'){emRemove($d,['Text 1','Text 2','Text 3']);emText($d,'Date',.82,.68,8,.38,(new DateTimeImmutable('now',new DateTimeZone('Europe/Zurich')))->format('d.m.Y'),18,'FFFFFF');emText($d,'Sujet',.82,1.25,8.5,1.15,$s['title'],34,'FFFFFF',true);emText($d,'Sous-titre',.82,2.55,8.3,1.05,$s['subtitle'],23,'FFFFFF');return;}
    emRemove($d,['Titre','Points de discussion','Validation attendue']);pptSetText($d,'Text 2',[(string)$number]);emText($d,'Titre EM',.55,.65,8.75,mb_strlen($s['title'])>60?.9:.56,$s['title'],mb_strlen($s['title'])>60?24:27,'202A25',true);emText($d,'Statut export',.57,4.78,8.4,.32,'Propositions à examiner · détails et sources dans les notes',12,'087A2A');
    switch($s['kind']){
    case 'overview':foreach($s['metrics'] as $i=>[$value,$label]){emText($d,'Valeur '.$i,.6+$i*3,1.55,2.8,.77,(string)$value,46,'087A2A',true);emText($d,'Sens '.$i,.6+$i*3,2.35,2.8,.7,$label,18);}foreach($s['lines'] as $i=>$line)emText($d,'Lecture '.$i,.65,3.35+$i*.37,8.6,.34,$line,17);break;
    case 'impacts':emTable($d,['Ce qui est exposé','Conséquence possible'],$s['rows'],[3.0,5.8],1.55,.8,20);break;
    case 'families':emTable($d,['Domaine','Risques concernés'],$s['rows'],[4.6,4.2],1.42,.40,18);break;
    case 'story':emText($d,'Si',.6,1.4,8.65,.35,'SI CETTE SITUATION SURVIENT',14,'087A2A',true);emText($d,'Scenario',.6,1.8,8.65,1.28,$s['scenario'],20);emText($d,'Alors',.6,3.15,8.65,.35,'CONSÉQUENCES POSSIBLES',14,'087A2A',true);emText($d,'Impact',.6,3.55,8.65,1.05,$s['impact'],20);break;
    case 'matrix':$cells=[];foreach($s['risks'] as $r)$cells[$r['data']['g'].'-'.$r['data']['p']][]=$r['code'];for($g=4;$g>=1;$g--){emText($d,'Gravite '.$g,.58,1.37+(4-$g)*.74,1.35,.72,$g.' · '.['','Limitée','Significative','Grave','Majeure'][$g],14,'202A25',true);for($p=1;$p<=4;$p++){$codes=$cells[$g.'-'.$p]??[];$txt=$codes?implode("\n",array_map(fn($a)=>implode(' ', $a),array_chunk($codes,3))):'—';if(count($codes)>9)$txt=count($codes).' risques'."\n".implode(' ',array_slice($codes,0,3))."\nDétail en notes";emText($d,'Matrice G'.$g.' P'.$p,2.0+($p-1)*1.75,1.37+(4-$g)*.74,1.70,.72,$txt,14,'202A25',true,emColor($g*$p),'ctr');}}for($p=1;$p<=4;$p++)emText($d,'Proba '.$p,2.0+($p-1)*1.75,4.36,1.70,.3,$p.' · '.['','Improbable','Possible','Probable','Quasi certain'][$p],14,'202A25',true,null,'ctr');emText($d,'Axes',.55,1.15,8.5,.2,'Gravité × vraisemblance · échelles de 1 à 4',12);emRemove($d,['Statut export']);emText($d,'Legende',.57,4.78,8.4,.32,'Faible 1–4 · Modéré 6–8 · Élevé 9–16 · cotations initiales proposées',12,'087A2A');break;
    case 'comparison':foreach(['Initiale proposée','Cible conditionnelle','Actuelle sur preuves'] as $i=>$l){emText($d,'Cotation '.$i,.6+$i*3,1.6,2.8,.6,$l,19,'087A2A',true);emText($d,'Valeur '.$i,.6+$i*3,2.3,2.8,1.1,$s['values'][$i],$i===2?27:48,'202A25',true);emText($d,'Limite '.$i,.6+$i*3,3.65,2.8,.7,['Point de départ du scénario','Efficacité à démontrer','À établir par réévaluation'][$i],18);}break;
    case 'actions':$labels=['planifiee'=>'Planifiées','en_cours'=>'En cours','preuve_soumise'=>'Preuves soumises','verifiee'=>'Vérifiées'];foreach(array_keys($labels) as $i=>$key){$v=$s['counts'][$key];$y=1.55+$i*.67;emText($d,'Etat '.$i,.6,$y,2.45,.46,$labels[$key],20);if($v>0)emText($d,'Barre '.$i,3.15,$y,max(.06,4.8*$v/max(1,$s['total'])),.43,'',18,'FFFFFF',false,$key==='verifiee'?'087A2A':'B9D8C1');emText($d,'Nombre '.$i,8.1,$y,.8,.46,(string)$v,24,'202A25',true);}emText($d,'Pas de preuve',.6,4.35,8.5,.3,'Une mesure prévue n’est pas encore une preuve d’efficacité',17);break;
    case 'calendar':emTable($d,['Date proposée','Mesures à planifier','Risques concernés'],$s['rows']?:[['À préciser','Aucune mesure individualisée','À préparer']],[2.15,3.15,3.5],1.42,.42,17);break;
    case 'measuretable':emTable($d,['Action proposée','Fonction proposée','Date'],$s['rows'],[4.5,2.9,1.4],1.42,.82,16);break;
    case 'decisions':emText($d,'Decision reelle',.6,1.35,8.7,.4,$s['decision_count']===0?'Aucune décision consignée dans la sélection':$s['decision_count'].' décision(s) consignée(s) · détail dans les notes',18,'087A2A',true);emTable($d,['À arbitrer','Question pour la direction'],$s['rows'],[3.25,5.55],1.95,.62,18);break;
    case 'aiplan':foreach($s['lines'] as $i=>$line)emText($d,'Proposition '.$i,.65,1.55+$i*1.5,8.6,1.35,$line,20);break;
    case 'annex':$r=$s['risk'];$v=$r['data'];emRemove($d,['Statut export']);emText($d,'Statut export',.57,5.02,8.4,.3,'Propositions à examiner · fiches intégrales dans les notes',12,'087A2A');emText($d,'Niveaux',.6,1.66,8.7,.45,'Initiale '.$v['score'].' · cible conditionnelle '.$v['target_score'].' · actuelle '.($v['current']['score']??'Non évaluée'),18,'087A2A',true);emTable($d,['Mesure proposée (abrégée)','Date proposée','État'],$s['rows']?:[['Mesures à individualiser','À préciser','À instruire']],[5.8,1.6,1.4],2.28,.63,16);emText($d,'Revue',.6,4.7,8.7,.25,'Revue de la fiche : '.emDate($v['next_review']).' · scénario, responsables, preuves et sources complets dans les notes',12);break;
    }
}
function makeEmPptx(array $risks,bool $annexes,bool $focus,string $output,?array $draft=null):array {
    $slides=emPlan($risks,$annexes,$focus);
    if($draft){$extra=[];try{$parts=presentationDraft($draft['output_text']);foreach($parts as $part)foreach(array_chunk($part['bullets'],2) as $chunk)$extra[]=['kind'=>'aiplan','title'=>'Piste IA · '.emLabel($part['title'],8),'lines'=>$chunk,'notes'=>'BROUILLON ASSISTANT IA À RELIRE. État : '.exportStatus($draft['disposition'])."\n".$part['notes']."\nTexte intégral du brouillon :\n".$draft['output_text']];}catch(InputError){$extra[]=['kind'=>'aiplan','title'=>'Proposition de l’Assistant IA à relire','lines'=>['Le brouillon choisi est joint dans les notes de cette diapositive.','Il ne remplace ni les mesures enregistrées ni une décision de gouvernance.'],'notes'=>'État : '.exportStatus($draft['disposition'])."\nTexte intégral :\n".$draft['output_text']];}$at=array_search('annex',array_column($slides,'kind'),true);array_splice($slides,$at===false?count($slides):$at,0,$extra);}
$template=dirname(__DIR__).'/templates/generic-reference.pptx';if(!copy($template,$output))throw new RuntimeException('Modèle Risques IA indisponible.');$zip=new ZipArchive();if($zip->open($output)!==true)throw new RuntimeException('Export indisponible.');
    try{$cover=$zip->getFromName('ppt/slides/slide1.xml');$body=$zip->getFromName('ppt/slides/slide2.xml');$relCover=$zip->getFromName('ppt/slides/_rels/slide1.xml.rels');$relBody=$zip->getFromName('ppt/slides/_rels/slide2.xml.rels');$notes=$zip->getFromName('ppt/notesSlides/notesSlide2.xml');$notesRel=$zip->getFromName('ppt/notesSlides/_rels/notesSlide2.xml.rels');
        $pres=pptDom($zip->getFromName('ppt/presentation.xml'));$xp=new DOMXPath($pres);$xp->registerNamespace('p',EM_P);$list=$xp->query('//p:sldIdLst')->item(0);while($list->firstChild)$list->removeChild($list->firstChild);
        $prels=pptDom($zip->getFromName('ppt/_rels/presentation.xml.rels'));foreach(iterator_to_array($prels->documentElement->childNodes) as $rel)if($rel instanceof DOMElement&&str_ends_with($rel->getAttribute('Type'),'/slide'))$prels->documentElement->removeChild($rel);
        $types=pptDom($zip->getFromName('[Content_Types].xml'));foreach(iterator_to_array($types->documentElement->childNodes) as $e)if($e instanceof DOMElement&&preg_match('~^/ppt/(slides/slide|notesSlides/notesSlide)\d+\.xml$~',$e->getAttribute('PartName')))$types->documentElement->removeChild($e);
        for($i=$zip->numFiles-1;$i>=0;$i--){$name=$zip->getNameIndex($i);if(preg_match('~^ppt/(?:slides/(?:_rels/)?slide|notesSlides/(?:_rels/)?notesSlide)\d+\.xml(?:\.rels)?$~',$name))$zip->deleteName($name);}
        foreach($slides as $index=>$s){$i=$index+1;$dom=pptDom($index===0?$cover:$body);emPaint($dom,$s,$i);$zip->addFromString('ppt/slides/slide'.$i.'.xml',$dom->saveXML());
            $rel=pptDom($index===0?$relCover:$relBody);foreach($rel->documentElement->childNodes as $e)if($e instanceof DOMElement&&str_ends_with($e->getAttribute('Type'),'/notesSlide'))$e->setAttribute('Target','/ppt/notesSlides/notesSlide'.$i.'.xml');$zip->addFromString('ppt/slides/_rels/slide'.$i.'.xml.rels',$rel->saveXML());
            $nd=pptDom($notes);pptNotes($nd,$s['title']."\n\n".$s['notes']);$zip->addFromString('ppt/notesSlides/notesSlide'.$i.'.xml',$nd->saveXML());$nr=pptDom($notesRel);foreach($nr->documentElement->childNodes as $e)if($e instanceof DOMElement&&str_ends_with($e->getAttribute('Type'),'/slide'))$e->setAttribute('Target','/ppt/slides/slide'.$i.'.xml');$zip->addFromString('ppt/notesSlides/_rels/notesSlide'.$i.'.xml.rels',$nr->saveXML());
            $sid=emNode($pres,EM_P,'p:sldId',['id'=>255+$i]);$sid->setAttributeNS('http://schemas.openxmlformats.org/officeDocument/2006/relationships','r:id','rEmSlide'.$i);$list->appendChild($sid);$prels->documentElement->appendChild(emNode($prels,'http://schemas.openxmlformats.org/package/2006/relationships','Relationship',['Id'=>'rEmSlide'.$i,'Type'=>'http://schemas.openxmlformats.org/officeDocument/2006/relationships/slide','Target'=>'slides/slide'.$i.'.xml']));
            foreach([['/ppt/slides/slide'.$i.'.xml','application/vnd.openxmlformats-officedocument.presentationml.slide+xml'],['/ppt/notesSlides/notesSlide'.$i.'.xml','application/vnd.openxmlformats-officedocument.presentationml.notesSlide+xml']] as [$part,$content])$types->documentElement->appendChild(emNode($types,'http://schemas.openxmlformats.org/package/2006/content-types','Override',['PartName'=>$part,'ContentType'=>$content]));
        }$zip->addFromString('ppt/presentation.xml',$pres->saveXML());$zip->addFromString('ppt/_rels/presentation.xml.rels',$prels->saveXML());$zip->addFromString('[Content_Types].xml',$types->saveXML());
        if($app=$zip->getFromName('docProps/app.xml')){$ad=pptDom($app);foreach($ad->getElementsByTagName('Slides') as $el)$el->nodeValue=(string)count($slides);foreach($ad->getElementsByTagName('Notes') as $el)$el->nodeValue=(string)count($slides);foreach(['HeadingPairs','TitlesOfParts'] as $tag)foreach(iterator_to_array($ad->getElementsByTagName($tag)) as $el)$el->parentNode->removeChild($el);$zip->addFromString('docProps/app.xml',$ad->saveXML());}
    }finally{$zip->close();}return $slides;
}
function sendEmPptx(Store $store,array $ids,bool $annexes,bool $focus,array $config):never {
    $risks=[];foreach($ids as $id)$risks[]=$store->detail($id);if($focus&&count($risks)!==1)throw new InputError('Choisissez un risque pour le zoom.');$path=tempnam($config['private_dir'],'em-export-');if($path===false)throw new RuntimeException('Export indisponible.');
    try{makeEmPptx($risks,$annexes,$focus,$path);header('Content-Type: application/vnd.openxmlformats-officedocument.presentationml.presentation');header('Content-Disposition: attachment; filename="Risques IA-'.($focus?$risks[0]['code']:'Etat-major').'-'.(new DateTimeImmutable('now',new DateTimeZone('Europe/Zurich')))->format('Y-m-d').'.pptx"');header('Content-Length: '.filesize($path));readfile($path);}finally{unlink($path);}exit;
}
